public static partial class MediaBinTest {
 static string root,log;static int passed;static readonly JavaScriptSerializer json=new JavaScriptSerializer();static readonly BindingFlags flags=BindingFlags.NonPublic|BindingFlags.Instance;
 static object Field(Editor e,string n){return typeof(Editor).GetField(n,flags).GetValue(e);}static void Set(Editor e,string n,object v){typeof(Editor).GetField(n,flags).SetValue(e,v);}static object Call(Editor e,string n,params object[] a){return typeof(Editor).GetMethod(n,flags).Invoke(e,a);}static Project P(Editor e){return (Project)Field(e,"project");}static int Undos(Editor e){return ((Stack<string>)Field(e,"undo")).Count;}
 static void Check(bool ok,string label){if(!ok)throw new Exception(label);passed++;File.AppendAllText(log,"PASS "+label+Environment.NewLine);}static Project Clone(Project p){return json.Deserialize<Project>(json.Serialize(p));}
 static IEnumerable<DependencyObject> Tree(DependencyObject n){yield return n;for(int i=0;i<VisualTreeHelper.GetChildrenCount(n);i++)foreach(var x in Tree(VisualTreeHelper.GetChild(n,i)))yield return x;}
 static byte[] Preview(LivePreview preview,Project p){preview.SetProject(p);preview.Seek(.5);preview.UpdateLayout();var bmp=new RenderTargetBitmap(p.Width,p.Height,96,96,PixelFormats.Pbgra32);bmp.Render(preview.Stage);var data=new byte[p.Width*p.Height*4];bmp.CopyPixels(data,p.Width*4,0);return data;}
 static byte[] Export(Project p,string name){string video=Path.Combine(root,name+".mp4"),rgb=Path.Combine(root,name+".rgb");Engine.Render(p,video,null);Engine.Run("ffmpeg","-y -v error -ss 0.5 -i "+Engine.Quote(video)+" -frames:v 1 -pix_fmt rgb24 -f rawvideo "+Engine.Quote(rgb));return File.ReadAllBytes(rgb);}
 static void Reset(Editor e,Project p){Set(e,"project",Clone(p));Set(e,"selected",null);Set(e,"openedGroupId",null);((Stack<string>)Field(e,"undo")).Clear();((Stack<string>)Field(e,"redo")).Clear();Set(e,"dirty",false);Call(e,"Refresh");}
 static void SortTests(Editor editor,Project p,LivePreview preview,byte[] pixels,byte[] export){
  var order=new Project();order.Media.AddRange(new[]{new Media{Id="z",Name="Zulu",Kind="image"},new Media{Id="a",Name="alpha",Kind="video"},new Media{Id="a2",Name="ALPHA",Kind="image"},new Media{Id="u",Name="日本",Kind="audio"},new Media{Id="n",Name=null,Kind="image"}});string model=json.Serialize(order);Check(string.Join(",",MediaBinOperations.View(order,"All media","Name",false).Select(m=>m.Id))=="n,a,a2,z,u","name ascending uses stable case-insensitive ordinal order");Check(string.Join(",",MediaBinOperations.View(order,"All media","Name",true).Select(m=>m.Id))=="u,z,a,a2,n","name descending reverses values but retains equal-name import order");Check(string.Join(",",MediaBinOperations.View(order,"All media","Type",false).Select(m=>m.Id))=="u,n,a2,z,a","type ascending uses name as its secondary key");Check(string.Join(",",MediaBinOperations.View(order,"All media","Type",true).Select(m=>m.Id))=="a,z,a2,n,u","type descending reverses both type and name keys");Check(MediaBinOperations.View(order,"Images","Name",true).Select(m=>m.Id).SequenceEqual(new[]{"z","a2","n"}),"type filter composes with descending name order");Check(MediaBinOperations.View(order,"Video","Type",false).Single().Id=="a","video view filters by metadata kind");Check(MediaBinOperations.View(order,"Audio","Name",false).Single().Id=="u","Unicode audio name remains selectable");Check(json.Serialize(order)==model,"all view queries preserve original media order and metadata");Check(MediaBinOperations.View(new Project(),"All media","Name",true).Count==0,"empty sorted view is valid");bool invalid=false;try{MediaBinOperations.View(order,"Unknown","Name",false);}catch(ArgumentException){invalid=true;}Check(invalid,"unsupported view filter rejected");invalid=false;try{MediaBinOperations.View(order,"All media","Duration",false);}catch(ArgumentException){invalid=true;}Check(invalid,"unimplemented sort field rejected");invalid=false;try{MediaBinOperations.View(null,"All media","Name",false);}catch(ArgumentException){invalid=true;}Check(invalid,"null sorted project rejected");
  Reset(editor,p);Set(editor,"mediaSort","Type");Set(editor,"mediaDescending",false);Call(editor,"Panel","Media");var bin=(ListBox)Field(editor,"bin");string id=p.Media[0].Id;bin.SelectedItem=bin.Items.OfType<ListBoxItem>().First(i=>i.Tag is Media&&((Media)i.Tag).Id==id);var library=(StackPanel)Field(editor,"library");var direction=Tree(library).OfType<Button>().First(b=>AutomationProperties.GetAutomationId(b)=="MediaSortDirection");Check((string)direction.ToolTip=="Ascending","sort direction starts with a descriptive Ascending tooltip");direction.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check((bool)Field(editor,"mediaDescending")&&(string)direction.ToolTip=="Descending","actual direction button switches to descending");Check(bin.Items.OfType<ListBoxItem>().Where(i=>i.Tag is Media).Select(i=>((Media)i.Tag).Id).SequenceEqual(MediaBinOperations.View(P(editor),"All media","Type",true).Select(m=>m.Id)),"direction button repopulates the actual bin in descending order");Check(bin.SelectedItems.Count==1&&((Media)((ListBoxItem)bin.SelectedItem).Tag).Id==id,"direction change retains the selected media ID");var sort=Tree(library).OfType<ComboBox>().First(c=>AutomationProperties.GetAutomationId(c)=="MediaSort");sort.SelectedItem="Name";Check(bin.SelectedItems.Count==1&&((Media)((ListBoxItem)bin.SelectedItem).Tag).Id==id,"sort-field change retains the selected entry");direction.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(!(bool)Field(editor,"mediaDescending")&&(string)direction.ToolTip=="Ascending","direction button toggles back to ascending");
  var layout=Tree(library).OfType<Button>().First(b=>(b.Content as string)=="☷ Details"||(b.Content as string)=="▦ Thumbnails");layout.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));bin=(ListBox)Field(editor,"bin");Check(bin.SelectedItems.Count==1&&((Media)((ListBoxItem)bin.SelectedItem).Tag).Id==id,"thumbnail/details layout change retains bin selection");Call(editor,"Panel","Annotations");Call(editor,"Panel","Media");bin=(ListBox)Field(editor,"bin");Check(bin.SelectedItems.Count==1&&((Media)((ListBoxItem)bin.SelectedItem).Tag).Id==id,"switching tools retains selection on the same project");Call(editor,"Refresh");bin=(ListBox)Field(editor,"bin");Check(bin.SelectedItems.Count==1&&((Media)((ListBoxItem)bin.SelectedItem).Tag).Id==id,"thumbnail/editor refresh retains selected media");var relink=Tree((StackPanel)Field(editor,"library")).OfType<Button>().First(b=>(b.Content as string)=="Relink Media...");Check(relink.IsEnabled,"retained single selection keeps Relink enabled after rebuild");
  string audioId=p.Media.Last().Id;bin.Items.OfType<ListBoxItem>().First(i=>i.Tag is Media&&((Media)i.Tag).Id==audioId).IsSelected=true;var filter=Tree((StackPanel)Field(editor,"library")).OfType<ComboBox>().First(c=>AutomationProperties.GetAutomationId(c)=="MediaFilter");filter.SelectedItem="Audio";Check(bin.SelectedItems.Count==1&&((Media)((ListBoxItem)bin.SelectedItem).Tag).Id==audioId,"filtering retains only visible selected entries");filter.SelectedItem="All media";Check(bin.SelectedItems.Count==1&&((Media)((ListBoxItem)bin.SelectedItem).Tag).Id==audioId,"clearing filter does not revive hidden stale selections");Check(json.Serialize(P(editor))==json.Serialize(p)&&Undos(editor)==0&&!(bool)Field(editor,"dirty"),"sorting filtering and layout changes leave project undo and dirty state untouched");Check(Preview(preview,P(editor)).SequenceEqual(pixels)&&Export(P(editor),"sorted").SequenceEqual(export),"sort and selection workflow preserves actual preview and decoded export");string file=Path.Combine(root,"sorted-project.tasiaproj");Engine.Save(P(editor),file);Check(json.Serialize(Engine.Load(file))==json.Serialize(p),"view state does not alter saved project data");Set(editor,"project",Clone(p));Call(editor,"Refresh");bin=(ListBox)Field(editor,"bin");Check(bin.SelectedItems.Count==0,"different project instance clears selection even when media IDs match");Check(!Tree((StackPanel)Field(editor,"library")).OfType<Button>().First(b=>(b.Content as string)=="Relink Media...").IsEnabled,"cleared project selection disables Relink");Set(editor,"mediaSort","Type");Set(editor,"mediaDescending",false);Set(editor,"mediaTiles",true);
 }
 static void Run(Editor editor,LivePreview preview){
  string redPath=Path.Combine(root,"red.png"),bluePath=Path.Combine(root,"blue.png"),wavePath=Path.Combine(root,"tone.wav");Engine.Run("ffmpeg","-y -v error -f lavfi -i color=red:s=320x180 -frames:v 1 "+Engine.Quote(redPath));Engine.Run("ffmpeg","-y -v error -f lavfi -i color=blue:s=320x180 -frames:v 1 "+Engine.Quote(bluePath));Engine.Run("ffmpeg","-y -v error -f lavfi -i sine=frequency=440:duration=1 "+Engine.Quote(wavePath));var files=new[]{redPath,bluePath,wavePath};var sourceBytes=files.Select(File.ReadAllBytes).ToArray();var used=Engine.Probe(redPath);var alias=Engine.Probe(redPath);alias.Name="Alias unused";var blue=Engine.Probe(bluePath);var wave=Engine.Probe(wavePath);var p=new Project{Width=320,Height=180,TrackCount=3};p.Media.AddRange(new[]{used,alias,blue,wave});p.Clips.Add(new Clip{MediaId=used.Id,Duration=1,Track=0});p.Clips.Add(new Clip{MediaId=used.Id,Duration=1,Track=1});p.HiddenTracks.Add(1);p.LockedTracks.Add(1);p.Groups.Add(new ClipGroup{Name="Protected group",ClipIds=p.Clips.Select(c=>c.Id).ToList()});Engine.Validate(p,false);string baseline=json.Serialize(p);var unused=MediaBinOperations.Unused(p);Check(unused.Count==3&&!unused.Contains(used),"unused lookup protects hidden locked grouped references");Check(unused.Contains(alias),"unused alias of a used source path identified by media ID");Check(json.Serialize(p)==baseline,"unused lookup is read-only");var streams=Clone(p);streams.Clips[0].Stream="video";streams.Clips[1].Stream="audio";Check(MediaBinOperations.Unused(streams).All(m=>m.Id!=used.Id),"separated stream halves keep their shared media reference");var empty=new Project();Check(MediaBinOperations.Unused(empty).Count==0&&MediaBinOperations.RemoveUnused(empty)==0,"empty project cleanup is a no-op");bool invalid=false;try{MediaBinOperations.Unused(null);}catch(ArgumentException){invalid=true;}Check(invalid,"null project rejected");var absent=Clone(p);absent.Media.Add(new Media{Path=Path.Combine(root,"absent.png"),Name="Absent unused",Kind="image",Width=320,Height=180,Duration=5});Check(MediaBinOperations.Unused(absent).Count==4,"unused missing source is identified without opening it");Check(MediaBinOperations.RemoveUnused(absent)==4,"unused missing source can be removed safely");Engine.Validate(absent,true);Check(absent.Media.Count==1,"cleanup leaves a valid exportable project after missing unused source");var onlyUnused=new Project();onlyUnused.Media.AddRange(p.Media);Check(MediaBinOperations.RemoveUnused(onlyUnused)==4&&onlyUnused.Media.Count==0,"all-unused project can clear the entire bin");var beforePreview=Preview(preview,p);var beforeExport=Export(p,"before");SortTests(editor,p,preview,beforePreview,beforeExport);PreviewTests(editor,p,preview,beforePreview,beforeExport);NavigationTests(editor,p,preview);BatchTests(editor,p,preview);DragTests(editor,p,preview);FailureTests(editor,p,preview,beforePreview,beforeExport);var cleaned=Clone(p);Check(MediaBinOperations.RemoveUnused(cleaned)==3,"cleanup removes all unused entries");Check(cleaned.Media.Count==1&&cleaned.Media[0].Id==used.Id,"cleanup retains the used entry sharing an unused path");Check(json.Serialize(cleaned.Clips)==json.Serialize(p.Clips)&&json.Serialize(cleaned.Groups)==json.Serialize(p.Groups),"cleanup preserves clip fields and group membership");Check(Preview(preview,cleaned).SequenceEqual(beforePreview),"cleanup leaves actual preview pixels unchanged");Check(Export(cleaned,"after").SequenceEqual(beforeExport),"cleanup leaves decoded export pixels unchanged");Check(MediaBinOperations.RemoveUnused(cleaned)==0,"repeat cleanup reports no change");string save=Path.Combine(root,"cleaned.tasiaproj");Engine.Save(cleaned,save);Check(json.Serialize(Engine.Load(save))==json.Serialize(cleaned),"cleaned project saves and reopens exactly");
  Reset(editor,p);Call(editor,"Panel","Media");Set(editor,"mediaFilter","Audio");Call(editor,"Panel","Media");var bin=(ListBox)Field(editor,"bin");Check(bin.Items.OfType<ListBoxItem>().Count(i=>i.Tag is Media)==1,"audio filter initially hides non-audio entries");Call(editor,"SelectUnusedMedia");bin=(ListBox)Field(editor,"bin");Check((string)Field(editor,"mediaFilter")=="All media"&&bin.Items.OfType<ListBoxItem>().Count(i=>i.Tag is Media)==4,"Select Unused reveals all media before selecting");Check(bin.SelectedItems.Count==3&&bin.SelectedItems.Cast<ListBoxItem>().All(i=>unused.Any(m=>m.Id==((Media)i.Tag).Id)),"Select Unused selects every unused entry only");Check(json.Serialize(P(editor))==baseline&&Undos(editor)==0&&!(bool)Field(editor,"dirty"),"bin selection leaves project undo and dirty state unchanged");Check(bin.SelectionMode==SelectionMode.Extended,"bin exposes multiple selection for unused entries");Check((bool)Call(editor,"MediaBinKey",System.Windows.Input.Key.A,System.Windows.Input.ModifierKeys.Control,true)&&bin.SelectedItems.Count==4,"focused bin Ctrl+A selects bin entries");Check((bool)Call(editor,"MediaBinKey",System.Windows.Input.Key.D,System.Windows.Input.ModifierKeys.Control|System.Windows.Input.ModifierKeys.Shift,true)&&bin.SelectedItems.Count==0,"focused bin deselect clears bin selection");Check((bool)Call(editor,"MediaBinKey",System.Windows.Input.Key.Delete,System.Windows.Input.ModifierKeys.None,true)&&json.Serialize(P(editor))==baseline&&Undos(editor)==0,"focused bin Delete cannot delete a timeline clip");Check((bool)Call(editor,"MediaBinKey",System.Windows.Input.Key.X,System.Windows.Input.ModifierKeys.Control,true)&&json.Serialize(P(editor))==baseline,"focused bin Cut cannot cut a timeline clip");Check(!(bool)Call(editor,"MediaBinKey",System.Windows.Input.Key.Delete,System.Windows.Input.ModifierKeys.None,false),"timeline key routing remains available outside bin focus");Call(editor,"SelectUnusedMedia");bin=(ListBox)Field(editor,"bin");var headers=bin.ContextMenu.Items.OfType<MenuItem>().Select(i=>(string)i.Header).ToList();Check(headers.Contains("Details")&&headers.Contains("Select Unused Media")&&headers.Contains("Delete Unused Media"),"bin context menu exposes documented command wording");var relink=Tree((StackPanel)Field(editor,"library")).OfType<Button>().First(b=>(b.Content as string)=="Relink Media...");Check(!relink.IsEnabled,"relink disabled for multiple selected entries");bin.SelectedItems.Clear();bin.SelectedItem=bin.Items.OfType<ListBoxItem>().First(i=>i.Tag is Media&&((Media)i.Tag).Id==used.Id);Check(relink.IsEnabled,"relink enabled for one real media item");string details=(string)Call(editor,"MediaDetailsText",P(editor).Media.First(m=>m.Id==used.Id));Check(details.Contains(redPath)&&details.Contains("320 × 180")&&details.Contains("Timeline references: 2")&&details.Contains("Available"),"Details reports stored metadata path availability and reference count");var missing=new Media{Path=Path.Combine(root,"missing.png"),Name="Missing",Kind="image"};Check(((string)Call(editor,"MediaDetailsText",missing)).Contains("Missing"),"Details reports a missing source honestly");bool dialogReadOnly=false;editor.Dispatcher.BeginInvoke(new Action(()=>{var dialog=Application.Current.Windows.Cast<Window>().First(w=>w.Title=="Media Details");var text=Tree(dialog).OfType<TextBox>().First(t=>AutomationProperties.GetAutomationId(t)=="Media.Details");dialogReadOnly=text.IsReadOnly&&text.Text==details;dialog.Close();}));Call(editor,"ShowMediaDetails");Check(dialogReadOnly,"actual Details dialog exposes a read-only metadata field");Check(json.Serialize(P(editor))==baseline&&Undos(editor)==0,"Details dialog leaves project and undo untouched");
  Set(editor,"mediaFilter","Audio");Call(editor,"Panel","Media");bin=(ListBox)Field(editor,"bin");bin.ContextMenu.Items.OfType<MenuItem>().First(i=>(string)i.Header=="Delete Unused Media").RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));Check(P(editor).Media.Count==1&&Undos(editor)==1,"context deletion ignores current filter and creates one checkpoint");Check(json.Serialize(P(editor).Clips)==json.Serialize(p.Clips),"editor deletion leaves every timeline clip unchanged");string postDelete=json.Serialize(P(editor));Check((bool)Field(editor,"dirty"),"deletion marks project dirty");Call(editor,"DeleteUnusedMedia");Check(Undos(editor)==1&&json.Serialize(P(editor))==postDelete,"no-op deletion creates no checkpoint");bin=(ListBox)Field(editor,"bin");Check(bin.Items.OfType<ListBoxItem>().Single().Tag==null&&((TextBlock)bin.Items.OfType<ListBoxItem>().Single().Content).Text=="No media matches the current filter.","empty filtered bin shows an honest no-match state");Call(editor,"Undo");Check(json.Serialize(P(editor))==baseline,"one undo restores every removed reference in original order"+(json.Serialize(P(editor))==baseline?"":" ACTUAL "+json.Serialize(P(editor))+" EXPECTED "+baseline));Call(editor,"Redo");Check(json.Serialize(P(editor))==postDelete,"one redo restores cleaned state");Engine.Save(P(editor),Path.Combine(root,"editor-cleaned.tasiaproj"));Check(json.Serialize(Engine.Load(Path.Combine(root,"editor-cleaned.tasiaproj")))==postDelete,"editor cleanup save reopens exactly");Reset(editor,p);Set(editor,"busy",true);Call(editor,"DeleteUnusedMedia");Call(editor,"SelectUnusedMedia");Check(json.Serialize(P(editor))==baseline&&Undos(editor)==0&&!(bool)Field(editor,"dirty"),"busy cleanup and selection are guarded without mutation");Set(editor,"busy",false);for(int i=0;i<files.Length;i++)Check(File.ReadAllBytes(files[i]).SequenceEqual(sourceBytes[i]),"all operations preserve source bytes "+i);
 }
 [STAThread]public static void Main(string[] args){root=args[0];Directory.CreateDirectory(root);log=Path.Combine(root,"results.txt");File.WriteAllText(log,"");var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var preview=new LivePreview();var host=new Window{Width=650,Height=400,Left=-20000,ShowInTaskbar=false,Content=preview};host.Loaded+=async(s,e)=>{Editor editor=null;int code=0;try{editor=new Editor{Left=-20000,Top=0,ShowInTaskbar=false};editor.Show();await Task.Delay(200);Call(editor,"HideHome");Run(editor,preview);File.AppendAllText(log,"PASS total "+passed+Environment.NewLine);}catch(Exception ex){File.AppendAllText(log,"FAIL "+ex+Environment.NewLine);code=1;}finally{if(editor!=null){Set(editor,"dirty",false);((LivePreview)Field(editor,"live")).Dispose();editor.Close();}preview.Dispose();host.Close();app.Shutdown(code);}};host.Show();app.Run();}
